        "Dice Rolls": "Primary: Dexterity + Firearms or Athletics(immolation); Wits + Composure (control). Secondary: Wits+ Weaponry (immolation); Wits + Survival (control).",
        "XP": "15, 12 for Long Night, 10 for Ascending",
