        "Summary": "Gain info about location as well as situational bonuses",
        "Required hunters": "3-5, 6+ is -1/per to any stealth",
        "Primary Requires": "Composure or Resolve 2, Wits 1, Investigation 1, Larceny 1, Stealth 1, Streetwise 1",
        "Secondary Requires": "Composure or Resolve 2, Wits 1, Investigation 1, (1) Investigation 2, Stealth 1, Streetwise 1",
        "Dice Rolls": "Primary: Wits + Intelligence; Secondary: Wits + Investigation",
        "XP": "16, 13 for Net 0, 11 for Aegis",
        "Book": "NS 131",
